<template><div class="container-page py-10"><NuxtLink to="/admin/properties" class="font-semibold text-primary-700">← Properties</NuxtLink><h1 class="mt-3 text-3xl">Add Property</h1><form class="card mt-7 space-y-6 p-6" @submit.prevent="save"><div class="grid gap-5 md:grid-cols-2"><div><label class="label">Estate name *</label><input v-model="form.name" class="input" required @input="syncSlug"/></div><div><label class="label">Slug *</label><input v-model="form.slug" class="input" required/></div><div><label class="label">Location *</label><select v-model="form.location_id" class="input" required @change="syncLocation"><option value="">Choose location</option><option v-for="l in locations" :key="l.id" :value="l.id">{{l.name}}</option></select></div><div><label class="label">Location detail *</label><input v-model="form.location_name" class="input" required/></div><div><label class="label">City *</label><input v-model="form.city" class="input" required/></div><div><label class="label">State *</label><input v-model="form.state" class="input" required/></div><div><label class="label">Starting price (NGN)</label><input v-model.number="form.price_from" class="input" type="number" min="0"/></div><div><label class="label">Pricing model</label><select v-model="form.pricing_model" class="input"><option value="all_inclusive">All inclusive</option><option value="plus_statutory_fees">Plus statutory fees</option><option value="contact_for_price">Contact for price</option></select></div><div><label class="label">Primary image</label><input class="input" type="file" accept="image/jpeg,image/png,image/webp,image/avif" @change="chooseFile"/></div></div><div><label class="label">Description</label><textarea v-model="form.description" class="input min-h-32"/></div><div class="grid gap-5 md:grid-cols-2"><div><label class="label">SEO title</label><input v-model="form.meta_title" class="input" maxlength="70"/></div><div><label class="label">Meta description</label><textarea v-model="form.meta_description" class="input" maxlength="170"/></div></div><label class="flex gap-2"><input v-model="form.featured" type="checkbox"/> Featured property</label><p v-if="error" class="rounded-lg bg-error-50 p-3 text-error-800">{{error}}</p><button class="btn-primary" :disabled="busy">{{busy?'Saving…':'Create Property'}}</button></form></div></template>
<script setup lang="ts">definePageMeta({layout:'admin',middleware:'admin-auth'});const db=useSupabase(),busy=ref(false),error=ref(''),file=ref<File|null>(null);const{data:locations}=useAsyncData('admin-locations',async()=>{const{data,error}=await db.from('locations').select('*').order('sort_order');if(error)throw error;return data||[]});const form=reactive({name:'',slug:'',location_id:'',location_name:'',city:'',state:'',country:'Nigeria',property_type:'land',status:'available',sales_status:'now_selling',developer:'Lexshield Properties Limited',price_from:null as number|null,pricing_model:'contact_for_price',featured:false,published:true,is_active:true,description:'',meta_title:'',meta_description:'',price_inclusive:false,last_price_verified_at:new Date().toISOString()});function syncSlug(){form.slug=form.name.toLowerCase().replace(/&/g,'and').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}function syncLocation(){const l=locations.value?.find(x=>x.id===form.location_id);if(l)form.state=l.state}function chooseFile(e:Event){file.value=(e.target as HTMLInputElement).files?.[0]||null}async function save(){busy.value=true;error.value='';try{form.price_inclusive=form.pricing_model==='all_inclusive';const{data:p,error:e}=await db.from('properties').insert({...form,price_display:form.price_from?`From ₦${Number((form.price_from/1e6).toFixed(2))}M`:null}).select().single();if(e)throw e;if(file.value){const ext=file.value.name.split('.').pop()||'jpg',path=`${p.id}/${crypto.randomUUID()}.${ext}`;const{error:u}=await db.storage.from('property-media').upload(path,file.value);if(u)throw u;const{data:url}=db.storage.from('property-media').getPublicUrl(path);await db.from('property_images').insert({property_id:p.id,image_url:url.publicUrl,alt_text:`${p.name} property`,is_primary:true});await db.from('properties').update({featured_image:url.publicUrl}).eq('id',p.id)}await navigateTo('/admin/properties')}catch(e:any){error.value=e.message||'Could not create property'}finally{busy.value=false}}useSeoMeta({title:'Add Property | Admin',robots:'noindex,nofollow'})</script>
